Route.hasMany(RouteMember, { foreignKey: "route_id", as: "routeMembers", onDelete: "CASCADE" });
RouteMember.belongsTo(Route, { foreignKey: "route_id", as: "route" });
RouteMember.belongsTo(Delegate, { foreignKey: "delegate_id", as: "delegate" });
